verification.testSuite:
const { getUserRole } = require('./lookup.js');
const map = new Map([
    ['u1', { role: 'admin' }]
]);
assert = require('assert');
assert.strictEqual(getUserRole(map, 'u1'), 'ADMIN');
assert.strictEqual(getUserRole(map, 'u2'), 'GUEST');
console.log('VERIFICATION_SUCCESS_STAGE_3');
process.exit(0);

